export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  let passed = true;
  const thresholdResults = [];

  if (thresholds) {
    for (const [metricId, min] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const metricScore = metric?.score;
      const thresholdPassed = typeof metricScore === 'number' && metricScore >= min;
      if (!thresholdPassed) passed = false;

      thresholdResults.push({
        metric: metricId,
        min,
        score: metricScore,
        passed: thresholdPassed
      });
    }
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds) {
    report.passed = passed;
    report.thresholds = thresholdResults;
  }

  return report;
}

