function parseThresholds(thresholdStrings?: string[]): { thresholds: Record<string, number> | null; error?: string } {
  if (!thresholdStrings || !thresholdStrings.length) {
    return { thresholds: null };
  }

  const thresholds: Record<string, number> = {};

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=(.+)$/);
    if (!match) {
      return { thresholds: null, error: `Invalid threshold format: "${thresholdStr}". Expected format: <metric>=<number>` };
    }

    const [, metricId, valueStr] = match;
    const value = Number.parseFloat(valueStr);

    if (Number.isNaN(value)) {
      return { thresholds: null, error: `Invalid threshold value: "${valueStr}" is not a number in "${thresholdStr}"` };
    }

    if (value < 0 || value > 1) {
      return { thresholds: null, error: `Invalid threshold value: ${value} must be between 0 and 1 (in "${thresholdStr}")` };
    }

    thresholds[metricId] = value;
  }

  return { thresholds };
}

function getValidMetricIds(evaluations: any[]): string[] {
  return evaluations.map((metric) => metric.id).sort();
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let thresholds: Record<string, number> | null = null;
  if (options.threshold) {
    const parseResult = parseThresholds(options.threshold);
    if (parseResult.error) {
      log.error(parseResult.error);
      process.exit(2);
    }
    if (parseResult.thresholds) {
      const validIds = getValidMetricIds(evaluations);
      const invalidMetrics = Object.keys(parseResult.thresholds).filter((id) => !validIds.includes(id));
      if (invalidMetrics.length > 0) {
        const error = `Unknown metric: "${invalidMetrics[0]}". Valid metrics are: ${validIds.join(', ')}`;
        log.error(error);
        process.exit(2);
      }
      thresholds = parseResult.thresholds;
    }
  }

  const generateReportConfig: any = {
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath
  };
  if (thresholds) {
    generateReportConfig.thresholds = thresholds;
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)(generateReportConfig);
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (report.passed === false) {
    process.exit(1);
  }
}

